update public.shop_category_attributes ca set required=false from public.shop_attribute_definitions a where ca.category_id='5cdc6a5a-8ce3-45ce-8669-a4d51d9e9051'::uuid and ca.attribute_definition_id=a.id and a.code in ('BRAND','MODEL') and ca.required=true;
