update public.shop_category_attributes ca set required=false from public.shop_attribute_definitions a where ca.category_id='46f2788b-2431-477b-897e-5e9dce3d1595'::uuid and ca.attribute_definition_id=a.id and a.code in ('BRAND','MODEL') and ca.required=true;
