delete from public.shop_category_attributes ca using public.shop_attribute_definitions a where ca.category_id='43f976c7-6f24-4b7b-81fa-b3f41a7717f8'::uuid and ca.attribute_definition_id=a.id and a.code in ('RAM','PROCESSOR');
do $$
begin
  if (select count(*) from public.shop_attribute_definitions where status = 'active') <> 45
